import{_ as a,o as t,c as r,a2 as i}from"./chunks/framework.DaGSOal_.js";const p=JSON.parse('{"title":"Glossary","description":"Common Unreal Engine concepts used in Deblx product guides.","frontmatter":{"title":"Glossary","description":"Common Unreal Engine concepts used in Deblx product guides."},"headers":[],"relativePath":"glossary.md","filePath":"glossary.md","lastUpdated":1794006476000}'),n={name:"glossary.md"};function o(s,e,l,d,c,u){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><h2 id="asset" tabindex="-1">Asset <a class="header-anchor" href="#asset" aria-label="Permalink to &quot;Asset&quot;">​</a></h2><p>A resource managed by Unreal Engine, such as a texture, material, mesh, audio file or Blueprint.</p><h2 id="blueprint" tabindex="-1">Blueprint <a class="header-anchor" href="#blueprint" aria-label="Permalink to &quot;Blueprint&quot;">​</a></h2><p>Unreal Engine&#39;s visual scripting system.</p><h2 id="content-browser" tabindex="-1">Content Browser <a class="header-anchor" href="#content-browser" aria-label="Permalink to &quot;Content Browser&quot;">​</a></h2><p>The editor interface for managing project assets and folders.</p><h2 id="data-asset" tabindex="-1">Data Asset <a class="header-anchor" href="#data-asset" aria-label="Permalink to &quot;Data Asset&quot;">​</a></h2><p>An Unreal Engine asset that stores editable configuration data. Loading Screen Pro uses Data Assets for its settings.</p><h2 id="editor-only-plugin" tabindex="-1">Editor-Only Plugin <a class="header-anchor" href="#editor-only-plugin" aria-label="Permalink to &quot;Editor-Only Plugin&quot;">​</a></h2><p>A plugin designed for editor workflows instead of packaged game functionality.</p><h2 id="package-packaged-build" tabindex="-1">Package / Packaged Build <a class="header-anchor" href="#package-packaged-build" aria-label="Permalink to &quot;Package / Packaged Build&quot;">​</a></h2><p>A built distribution of your project. Runtime features can behave differently in packaged builds and Play-in-Editor.</p><h2 id="pie-play-in-editor" tabindex="-1">PIE (Play-in-Editor) <a class="header-anchor" href="#pie-play-in-editor" aria-label="Permalink to &quot;PIE (Play-in-Editor)&quot;">​</a></h2><p>Testing a project within the Unreal Editor.</p><h2 id="referencer" tabindex="-1">Referencer <a class="header-anchor" href="#referencer" aria-label="Permalink to &quot;Referencer&quot;">​</a></h2><p>An object or asset that references another asset. This information is important when reviewing duplicate cleanup operations.</p><h2 id="redirector" tabindex="-1">Redirector <a class="header-anchor" href="#redirector" aria-label="Permalink to &quot;Redirector&quot;">​</a></h2><p>An Unreal Engine mechanism for preserving references to moved or consolidated assets.</p><h2 id="runtime-memory-estimate" tabindex="-1">Runtime Memory Estimate <a class="header-anchor" href="#runtime-memory-estimate" aria-label="Permalink to &quot;Runtime Memory Estimate&quot;">​</a></h2><p>An approximation of memory used by an asset at runtime. Actual usage varies with engine settings, compression and streaming.</p><h2 id="related-guides" tabindex="-1">Related Guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to &quot;Related Guides&quot;">​</a></h2><ul><li><a href="/loading-screen-pro/">Loading Screen Pro</a></li><li><a href="/quick-notes/">Quick Notes / ToDo</a></li><li><a href="/duplicate-asset-detector/">Duplicate Asset Detector Pro</a></li><li><a href="/asset-size-analyzer/">Asset Size Analyzer</a></li></ul>',23)])])}const m=a(n,[["render",o]]);export{p as __pageData,m as default};
